package it.universita.nis2.service;
import it.universita.nis2.model.*;
import it.universita.nis2.repo.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.time.*;
import java.security.MessageDigest;
import java.util.*;
@Service public class IncidentService {
private final IncidentRepository incidents; private final SubmissionRepository submissions; private final ReclassificationRepository changes; private final CategoryRepository categories; private final ObjectMapper mapper;
public IncidentService(IncidentRepository i,SubmissionRepository s,ReclassificationRepository r,CategoryRepository c,ObjectMapper m){incidents=i;submissions=s;changes=r;categories=c;mapper=m;}
public Incident get(Long id){return incidents.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Incidente inesistente"));}
public List<Incident> all(){return incidents.findAll();}
public List<Submission> submissions(Long id){get(id);return submissions.findByIncidentIdOrderByCreatedAtAsc(id);}
public List<Reclassification> changes(Long id){get(id);return changes.findByIncidentIdOrderByChangedAtAsc(id);}
private void validateCategory(Incident i){Category c=categories.findById(i.category).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Codice ACN non riconosciuto"));if("ESSENZIALE".equals(i.entityType)) return;if(!"IMPORTANTE".equals(i.entityType)||"ESSENZIALE".equals(c.applicableTo))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Categoria incompatibile con il soggetto");}
@Transactional public Incident create(Incident i){i.id=null;i.status="BOZZA";validateCategory(i);i.createdAt=LocalDateTime.now();i.updatedAt=i.createdAt;return incidents.save(i);}
@Transactional public Incident update(Long id,Incident input){Incident i=get(id);validateCategory(input);if(!submissions.findByIncidentIdOrderByCreatedAtAsc(id).isEmpty()&&!i.category.equals(input.category)) throw new ResponseStatusException(HttpStatus.CONFLICT,"Per cambiare categoria dopo un invio usare riclassificazione");i.title=input.title;i.description=input.description;i.knownAt=input.knownAt;i.entityType=input.entityType;i.category=input.category;i.usersAffected=input.usersAffected;i.downtimeMinutes=input.downtimeMinutes;i.externalDataLoss=input.externalDataLoss;i.externalIntegrityLoss=input.externalIntegrityLoss;i.slaViolated=input.slaViolated;i.unauthorizedAccess=input.unauthorizedAccess;i.updatedAt=LocalDateTime.now();return incidents.save(i);}
public boolean significant(Incident i){return switch(i.category){case "IS-1" -> i.externalDataLoss;case "IS-2" -> i.externalIntegrityLoss;case "IS-3" -> i.slaViolated;case "IS-4" -> "ESSENZIALE".equals(i.entityType)&&i.unauthorizedAccess;default -> false;};}
public Map<String,Object> assessment(Long id){Incident i=get(id);boolean yes=significant(i);return Map.of("sogliaDidatticaSuperata",SignificativitaDidattica.superaSoglia(i),"significant",yes,"reason",yes?"Condizione dimostrativa soddisfatta":"Condizione dimostrativa non soddisfatta","warning","Regole semplificate didattiche: NON sostituiscono gli allegati ACN o la valutazione normativa","deadline24",i.knownAt.plusHours(24),"deadline72",i.knownAt.plusHours(72),"deadlineFinal",i.knownAt.plusMonths(1));}
@Transactional public Submission submit(Long id,String phase){Incident i=get(id);NotificationValidation.validateBase(i);if("PRENOTIFICA".equals(phase)){NotificationValidation.validatePrenotifica(i);}if("NOTIFICA".equals(phase)){NotificationValidation.validateNotifica(i);}if("FINALE".equals(phase)){NotificationValidation.validateFinale(i);}if(!Set.of("PRENOTIFICA","NOTIFICA","FINALE").contains(phase))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Fase non valida");if(!significant(i))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Soglia didattica non soddisfatta");List<Submission> previous=submissions(id);if(previous.stream().anyMatch(s->s.phase.equals(phase)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Fase già congelata");if(phase.equals("NOTIFICA")&&previous.stream().noneMatch(s->s.phase.equals("PRENOTIFICA")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Prima completare pre-notifica");if(phase.equals("FINALE")&&previous.stream().noneMatch(s->s.phase.equals("NOTIFICA")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Prima completare notifica");if(i.title==null||i.title.isBlank()||i.description==null||i.description.isBlank()||i.knownAt==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Campi di base mancanti");if(phase.equals("FINALE")&&i.description.length()<30)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"La relazione finale richiede una descrizione di almeno 30 caratteri (regola dimostrativa)");try{Submission s=new Submission();s.incidentId=id;s.phase=phase;s.categoryAtSubmission=i.category;s.createdAt=LocalDateTime.now();Map<String,Object> snapshot=new LinkedHashMap<>();snapshot.put("fase",phase);snapshot.put("dataCongelamento",s.createdAt.toString());snapshot.put("incidenteId",id);snapshot.put("titolo",i.title);snapshot.put("descrizione",i.description);snapshot.put("conoscenzaEvento",i.knownAt.toString());snapshot.put("classificazione",i.category);snapshot.put("tipoSoggetto",i.entityType);snapshot.put("utentiCoinvolti",i.usersAffected);snapshot.put("minutiInterruzione",i.downtimeMinutes);snapshot.put("perditaRiservatezzaEsterna",i.externalDataLoss);snapshot.put("perditaIntegritaEsterna",i.externalIntegrityLoss);snapshot.put("livelloServizioViolato",i.slaViolated);snapshot.put("accessoNonAutorizzato",i.unauthorizedAccess);if(phase.equals("FINALE")){List<Map<String,Object>> storico=new ArrayList<>();for(Reclassification r:changes.findByIncidentIdOrderByChangedAtAsc(id)){Map<String,Object> voce=new LinkedHashMap<>();voce.put("categoriaPrecedente",r.fromCategory);voce.put("categoriaNuova",r.toCategory);voce.put("dataRiclassificazione",r.changedAt.toString());voce.put("motivazione",r.reason);storico.add(voce);}snapshot.put("storicoRiclassificazioni",storico);}snapshot.put("nota","SIMULAZIONE - documento non trasmesso al CSIRT Italia");s.snapshotJson=mapper.writerWithDefaultPrettyPrinter().writeValueAsString(snapshot);s.sha256=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.snapshotJson.getBytes(java.nio.charset.StandardCharsets.UTF_8)));i.status=phase;i.updatedAt=s.createdAt;incidents.save(i);return submissions.save(s);}catch(Exception e){throw new IllegalStateException(e);}}
@Transactional public Reclassification reclassify(Long id,String newCategory,String reason){Incident i=get(id);if(reason==null||reason.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Motivazione obbligatoria");String old=i.category;i.category=newCategory;validateCategory(i);if(old.equals(newCategory))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"La nuova categoria deve essere diversa");Reclassification c=new Reclassification();c.incidentId=id;c.fromCategory=old;c.toCategory=newCategory;c.reason=reason;c.changedAt=LocalDateTime.now();i.updatedAt=c.changedAt;incidents.save(i);return changes.save(c);}
}
